        if n == 0 or n == 1:
            return 1
        result = 1
        for i in range(2, n + 1):
            result *= i
        return result

    low, high = 1, 10**6
    while low <= high:
        mid = (low + high) // 2
        mid_factorial = factorial(mid)
        if mid_factorial == factorial_value:
            return mid
        elif mid_factorial < factorial_value:
            low = mid + 1
        else:
            high = mid - 1
    return -1

