import sys
import math

def find_factorial_n(factorial_value):
    if factorial_value == 1:
        return 1

    # Estimate the range for n using logarithms
    low, high = 1, int(math.log10(factorial_value)) + 1

    while low < high:
        mid = (low + high) // 2
        mid_factorial = math.factorial(mid)

        if mid_factorial == factorial_value:
            return mid
        elif mid_factorial < factorial_value:
            low = mid + 1
        else:
            high = mid

    return low - 1

